import asyncio, websockets, json, os
from datetime import datetime, timezone
from savant.services.ai_core.quantum_graph_engine import QuantumGraphEngine, record_cycle
BASE = os.path.expanduser("~/savant/context")
graph = QuantumGraphEngine()

async def handler(ws):
    async for message in ws:
        try:
            payload=json.loads(message)
            source=payload.get("source","unknown")
            conf=float(payload.get("confidence",0.5))
            rels=payload.get("relations",[])
            graph.add_inference(source,conf,rels)
            record_cycle(payload)
            await ws.send(json.dumps({"status":"ok","received":source}))
        except Exception as e:
            await ws.send(json.dumps({"error":str(e)}))

async def main():
    port=9091
    print(f"🌐 Federation Inference Broker listening on ws://0.0.0.0:{port}")
    async with websockets.serve(handler,"0.0.0.0",port):
        await asyncio.Future()

if __name__=="__main__":
    asyncio.run(main())


